contract InvMutTest {
    C c;
    uint public calls;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {
        calls++;
    }

    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length > 0);
        require(_tos.length == v.length);
        calls = 0;
        c.transfer(from, caddress, _tos, v);
        assert(calls <= _tos.length * v.length);
    }
}

