contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory tos, uint[] memory v) public payable {
        require(tos.length > 0);
        require(tos.length == v.length);

        bool ok;
        bool reverted;
        try c.transfer(from, caddress, tos, v) returns (bool _ok) {
            ok = _ok;
            reverted = false;
        } catch {
            reverted = true;
        }

        // P returns true exactly when no forwarded token call failed (i.e., all succeeded),
        // and false is impossible. If any forwarded call reverts, the whole call reverts.
        assert(!reverted && ok);
    }

    receive() external payable {}
}

